const seen = new Set();
const perRepo = {};
for (const it of $input.all()) {
  const { repo, path } = it.json;
  const k = repo + '::' + path;
  if (seen.has(k)) continue;
  seen.add(k);
  perRepo[repo] = perRepo[repo] || [];
  perRepo[repo].push(path);
}
const out = [];
for (const repo of Object.keys(perRepo).sort()) {
  const paths = perRepo[repo]
    .sort((a,b) => {
      const sa = /i18n|locale|lang|routing|config/i.test(a) ? 0 : 1;
      const sb = /i18n|locale|lang|routing|config/i.test(b) ? 0 : 1;
      return sa - sb || a.length - b.length;
    })
    .slice(0, 8);
  for (const p of paths) out.push({ json: { repo, path: p } });
}
return out;

const rows = $input.all().map(i => i.json).filter(r => r.count > 0 || r.env_driven);
const byRepo = {};
for (const r of rows) {
  byRepo[r.repo] = byRepo[r.repo] || [];
  byRepo[r.repo].push(r);
}
const out = [];
for (const repo of Object.keys(byRepo).sort()) {
  const files = byRepo[repo].sort((a,b) => b.count - a.count);
  const literal = files.filter(f => f.count > 1 && !f.env_driven);
  const env = files.filter(f => f.env_driven);
  let status, declared = [];
  if (env.length && !literal.length) {
    status = 'set at runtime by ' + (env[0].env_var || 'an env var');
  } else if (literal.length) {
    declared = literal[0].declared;
    status = 'static list in ' + literal[0].path;
    const disagree = literal.filter(f => f.declared.join(',') !== literal[0].declared.join(','));
    if (disagree.length) status += ' (conflicts with ' + disagree[0].path + ')';
    if (env.length) status += '; also an env fallback in ' + env[0].path;
  } else {
    status = 'only a default locale found, no list';
  }
  out.push({
    repo, status, declared,
    env_driven: !!env.length && !literal.length,
    files: files.map(f => ({ path: f.path, declared: f.declared, env_driven: f.env_driven, env_var: f.env_var }))
  });
}
return [{ json: { repos: out.length, detail: out } }];

const meta = $('File Loop').first().json;
const b = ($input.first().json || {}).body || {};
let text = '';
try { if (b.content) text = Buffer.from(b.content, b.encoding || 'base64').toString('utf8'); } catch (e) {}

const ISO = new Set(('cs da de el en es et fi fil fr hr hu id it ja ko lt lv ms nl no pl pt ro sk sl sv th tr uk vi zh ar ru he hi nb nn')
  .split(/\s+/));

const found = {};
let envDriven = false;
let envVar = null;

const BRACKET = /\[([^\[\]]{0,1500})\]/g;
let m;
while ((m = BRACKET.exec(text)) !== null) {
  const before = text.slice(Math.max(0, m.index - 140), m.index);
  if (!/locale|lang|i18n/i.test(before)) continue;
  const inner = m[1];
  const toks = inner.match(/(?:['\"`]([a-zA-Z_-]{2,6})['\"`])|(?::([a-z]{2,3}(?:[_-][a-zA-Z]{2,4})?)\b)/g) || [];
  if (!toks.length) continue;
  const vals = toks.map(t => t.replace(/['\"`:]/g, '').replace('-', '_'));
  const ok = vals.every(v => ISO.has(v) || ISO.has(v.split('_')[0]));
  if (!ok) continue;

  // Is this literal actually a fallback for a runtime-configured list?
  const ctx = before + inner + text.slice(m.index + m[0].length, m.index + m[0].length + 60);
  const envMatch = ctx.match(/process\.env\.([A-Z0-9_]+)|ENV\[['\"]([A-Z0-9_]+)['\"]\]|Deno\.env\.get\(['\"]([A-Z0-9_]+)['\"]\)/);
  if (envMatch && /\?\?|\|\||fallback|default/i.test(ctx)) {
    envDriven = true;
    envVar = envVar || envMatch[1] || envMatch[2] || envMatch[3];
    continue;
  }
  for (const v of vals) found[v] = true;
}

if (!envDriven) {
  const envAny = text.match(/(?:process\.env\.|ENV\[['\"]|Deno\.env\.get\(['\"])([A-Z0-9_]*(?:LOCALE|LANGUAGE)[A-Z0-9_]*)/);
  if (envAny) { envDriven = true; envVar = envAny[1]; }
}

const def = text.match(/(?:DEFAULT_LOCALE|defaultLocale)\s*[:=]\s*['\"`]([a-zA-Z_-]{2,6})['\"`]/);
const defaultLocale = def ? def[1].replace('-', '_') : null;

const declared = Object.keys(found).sort();
return [{ json: {
  repo: meta.repo,
  path: meta.path,
  declared,
  count: declared.length,
  env_driven: envDriven,
  env_var: envVar,
  default_locale: defaultLocale
}}];

const b = ($input.first().json || {}).body || {};
const items = Array.isArray(b.items) ? b.items : [];
const SKIP = /(^|\/)(node_modules|dist|build|\.next|vendor|coverage|spec|test|tests|__tests__)(\/|$)/i;
const out = [];
for (const it of items) {
  const repo = it.repository && it.repository.name;
  const path = it.path;
  if (!repo || !path) continue;
  if (SKIP.test(path)) continue;
  if (/\.(md|lock|snap|env.*|Dockerfile)$/i.test(path)) continue;
  if (!/\.(ts|tsx|js|mjs|cjs|rb|json)$/i.test(path)) continue;
  out.push({ json: { repo, path } });
}
return out;
